const raiseIncidentSeverity = `-- name: RaiseIncidentSeverity :execrows
UPDATE pc.incidents SET severity = $1::text, updated_at = now()
WHERE org_id = $2 AND id = $3
  AND array_position(ARRAY['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'], severity)
      < array_position(ARRAY['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'], $1::text)
`

// Severity only goes up as alerts attach.
func (q *Queries) RaiseIncidentSeverity(ctx context.Context, severity string, orgID ids.OrgID, iD ids.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, raiseIncidentSeverity, severity, orgID, iD)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reopenSuppressedAlert = `-- name: ReopenSuppressedAlert :execrows

UPDATE pc.alerts SET state = 'OPEN', suppression_id = NULL, updated_at = now()
WHERE org_id = $1 AND id = $2 AND state = 'SUPPRESSED'
`

// SPDX-License-Identifier: BUSL-1.1
// Copyright (c) 2026 Joshua Kato. See LICENSE and NOTICE.
//
// Alerts, incidents, suppressions, owned failures and digests (G0 M10
// D14–D18; HR-242, HR-243). Every query runs inside db.InTenantTx and also
// filters by org_id explicitly.
// A suppressed alert reopens when a signal bypasses or outlives its
// suppression (D16, HR-242).
func (q *Queries) ReopenSuppressedAlert(ctx context.Context, orgID ids.OrgID, iD ids.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, reopenSuppressedAlert, orgID, iD)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const reopenUnsuppressedAlerts = `-- name: ReopenUnsuppressedAlerts :many
UPDATE pc.alerts a SET state = 'OPEN', suppression_id = NULL, updated_at = now()
FROM pc.suppressions s
WHERE a.org_id = $1 AND a.state = 'SUPPRESSED' AND s.org_id = a.org_id AND s.id = a.suppression_id
  AND (s.ended_at IS NOT NULL OR s.expires_at <= now())
RETURNING a.id
`

// Suppressed alerts whose suppression ended or expired open again (D59 M1).
func (q *Queries) ReopenUnsuppressedAlerts(ctx context.Context, orgID ids.OrgID) ([]ids.UUID, error) {
	rows, err := q.db.Query(ctx, reopenUnsuppressedAlerts, orgID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ids.UUID{}
	for rows.Next() {
		var id ids.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

